'use client';
// Compliance calendar: the calendar views (month, week, list), reusable templates and bulk setup.
//
// What gets created is decided by the server only (calendarPreview / calendarApply in
// backend/app/services/calendar_service.py): this page collects the choices, shows the server's
// plan and sends the companies one at a time so progress can be shown. Generated entries are
// ordinary tasks, opened in the workspace's existing record drawer.
import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import Dialog from './dialog';
import { AlertCircle, Archive, Building2, CalendarDays, Check, CheckCircle2, ChevronLeft, ChevronRight, Copy, Eye, Layers, ListChecks, Loader2, Pencil, Plus, RotateCcw, Search, ShieldCheck, X } from 'lucide-react';

type R = { id: string; kind: string; revision: number;[key: string]: any };
type Reminders = { days: number[]; overdue: boolean };
type Activity = { id?: string; key: string; name: string; category: string; frequency: string; dueDay: string; monthsAfter: string; role: string; reminders: Reminders; instructions: string; dateBasis: string; verifyDates: boolean; filing: boolean; clientVisible: boolean };
type Draft = { id?: string; revision?: number; name: string; description: string; companyType: string; financialYear: string; secretaryApply: boolean; activities: Activity[] };
type Result = { company: string; name: string; status: string; created: number; existing: number; duplicates: number; ruleCovered: number; excluded: number; past: number; needsConfirmation: number; published?: number; error: string };
export type CalendarMode = 'calendar' | 'bulk' | 'templates';

const COMPANY_TYPES = ['Private limited company', 'One Person Company', 'Public limited company', 'Section 8 company', 'Other — secretary to confirm'];
const FREQUENCIES = ['Monthly', 'Quarterly', 'Half-yearly', 'Annual'];
const ROLES = ['Secretary', 'Accountant', 'Owner', 'Director'];
const REMINDER_DAYS = [30, 15, 7, 3, 1, 0];
const CALENDAR_KINDS = ['task', 'meeting', 'close', 'request'];
const SETTLED = ['Completed', 'Closed', 'Cancelled'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const ENTRY_STATUS: Record<string, string> = { new: 'Will create', exists: 'Already created', duplicate: 'Duplicate skipped', rule: 'Rule library', excluded: 'Excluded', past: 'Past due date' };

const fmt = (v?: string) => v ? new Date(v + 'T12:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const fyOf = (day: string) => { const y = +day.slice(0, 4), s = +day.slice(5, 7) >= 4 ? y : y - 1; return `${s}-${String((s + 1) % 100).padStart(2, '0')}` };
const shiftFy = (fy: string, n: number) => { const s = +fy.slice(0, 4) + n; return `${s}-${String((s + 1) % 100).padStart(2, '0')}` };
const initials = (v: string) => (v || '—').split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase();
const plural = (n: number, one: string, many = one + 's') => `${n} ${n === 1 ? one : many}`;
export const origin = (r: R) => r.template ? 'Template' : r.rule ? 'Rule library' : 'Individual';
const categoryOf = (r: R) => r.kind === 'task' ? (r.category || 'Compliance') : ({ meeting: 'Board meeting', close: 'Financial close', request: 'Client request' } as Record<string, string>)[r.kind] || r.kind;
/** A template entry whose date has not been verified for its company (or was changed after it was). */
export const unverified = (r: R) => !!r.template?.verify && !(r.template.dateConfirmed && (!r.template.confirmedDue || r.template.confirmedDue === r.due));
export function reminderText(rem?: Reminders) {
    if (!rem || !Array.isArray(rem.days)) return 'Standard: daily from three days before the due date';
    const before = rem.days.filter(d => d > 0), parts = [];
    if (before.length) parts.push(before.join(', ') + ' day' + (before.length === 1 && before[0] === 1 ? '' : 's') + ' before');
    if (rem.days.includes(0)) parts.push('on the due date');
    if (rem.overdue) parts.push('daily once overdue');
    return parts.length ? parts.join(' · ') : 'No reminders';
}
const tone = (s: string) => ['Completed', 'Approved', 'Reviewed', 'Closed', 'Accepted', 'Published', 'Active', 'Will create', 'Eligible', 'Date verified'].includes(s) ? 'success' : ['Overdue', 'Rejected', 'Returned', 'Cancelled', 'Failed', 'Inactive', 'Not eligible'].includes(s) ? 'danger' : ['Under review', 'Responded', 'Authorised', 'Rule library', 'Partially failed'].includes(s) ? 'violet' : ['Awaiting information', 'Review required', 'Draft', 'To be verified', 'Archived', 'Duplicate skipped', 'In progress run'].includes(s) ? 'warning' : 'neutral';
function Pill({ value }: { value: string }) { return <span className={'pill ' + tone(value)}><i />{value}</span> }
function Empty({ title, body, action }: { title: string; body: string; action?: any }) { return <div className="empty-state"><span><CalendarDays size={26} /></span><h3>{title}</h3><p>{body}</p>{action}</div> }

async function post(body: any) {
    const response = await fetch('/api/v2', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const data: any = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || `The request failed (${response.status}).`);
    return data;
}

/** Example rule for the editor: what the first period's date would be (the server computes the real plan). */
function example(a: Activity, fy: string) {
    const size = ({ Monthly: 1, Quarterly: 3, 'Half-yearly': 6, Annual: 12 } as Record<string, number>)[a.frequency] || 1, day = Math.min(31, Math.max(1, +a.dueDay || 1)), after = Math.min(12, Math.max(0, +a.monthsAfter || 0));
    const start = +fy.slice(0, 4) * 12 + 3, end = start + size - 1 + after, y = Math.floor(end / 12), m = end % 12, last = new Date(y, m + 1, 0).getDate();
    const label = size === 1 ? `${MONTHS[3]} ${fy.slice(0, 4)}` : size === 12 ? `FY ${fy}` : `${size === 3 ? 'Q1' : 'H1'} FY ${fy}`;
    return `${label} → ${fmt(iso(new Date(y, m, Math.min(day, last))))}`;
}

const blankActivity = (): Activity => ({ key: crypto.randomUUID(), name: '', category: 'Compliance', frequency: 'Monthly', dueDay: '20', monthsAfter: '1', role: 'Secretary', reminders: { days: [7, 3, 1], overdue: true }, instructions: '', dateBasis: '', verifyDates: true, filing: false, clientVisible: false });
// The example from the requirements: names and frequencies only. The days are placeholders that every
// company's date check must confirm; they are not presented as statutory deadlines.
const exampleActivities = (): Activity[] => [
    { ...blankActivity(), name: 'GST Return', category: 'GST', frequency: 'Monthly', dueDay: '11', monthsAfter: '1', dateBasis: 'Verify the GST due date for each return period', clientVisible: true },
    { ...blankActivity(), name: 'TDS Return', category: 'TDS', frequency: 'Quarterly', dueDay: '31', monthsAfter: '1', role: 'Accountant', dateBasis: 'Verify the TDS statement due date for each quarter' },
    { ...blankActivity(), name: 'Annual Compliance Review', category: 'Annual compliance', frequency: 'Annual', dueDay: '30', monthsAfter: '6', verifyDates: false, instructions: 'Internal review of the year’s registers, filings and approvals.' },
    { ...blankActivity(), name: 'Annual Filing', category: 'Annual filing', frequency: 'Annual', dueDay: '30', monthsAfter: '7', filing: true, dateBasis: 'Depends on the AGM date: verify for each company' },
];

export default function ComplianceCalendar(props: {
    records: R[]; display: R[]; members: R[]; companies: R[]; actor: any; today: string; mode: CalendarMode; setMode: (m: CalendarMode) => void;
    name: (id: string) => string; member: (id: string) => string; inspect: (r: R) => void; createEntry: () => void; reload: () => Promise<any>; notify: (message: string) => void; audit: any[];
}) {
    const { records, actor, mode, setMode } = props;
    const templates = records.filter(r => r.kind === 'calendartemplate');
    const owner = actor.role === 'Owner', canEdit = ['Owner', 'Secretary', 'Accountant'].includes(actor.role);
    const usable = templates.filter(t => t.status === 'Active' && (owner || (actor.role === 'Secretary' && t.secretaryApply === true)));
    const canBulk = owner || (actor.role === 'Secretary' && usable.length > 0);
    const [applyWith, setApplyWith] = useState('');
    useEffect(() => { if (mode === 'bulk' && !canBulk) setMode('calendar') }, [mode, canBulk, setMode]);
    return <>
        <div className="cal-tabs" role="tablist" aria-label="Compliance calendar">
            <div className="segmented">
                <button role="tab" aria-selected={mode === 'calendar'} className={mode === 'calendar' ? 'on' : ''} onClick={() => setMode('calendar')}><CalendarDays size={14} />Calendar</button>
                {canBulk && <button role="tab" aria-selected={mode === 'bulk'} className={mode === 'bulk' ? 'on' : ''} onClick={() => { setApplyWith(''); setMode('bulk') }}><Layers size={14} />Bulk setup</button>}
                <button role="tab" aria-selected={mode === 'templates'} className={mode === 'templates' ? 'on' : ''} onClick={() => setMode('templates')}><ListChecks size={14} />Manage templates</button>
            </div>
            {canEdit && <button className="btn secondary" onClick={props.createEntry} title="Schedule one compliance entry for one company"><Plus size={16} />Individual setup</button>}
        </div>
        {mode === 'calendar' && <CalendarViews {...props} />}
        {mode === 'templates' && <TemplateManager {...props} templates={templates} owner={owner} canApply={(t: R) => t.status === 'Active' && (owner || (actor.role === 'Secretary' && t.secretaryApply === true))} onApply={(t: R) => { setApplyWith(t.id); setMode('bulk') }} />}
        {mode === 'bulk' && canBulk && <BulkSetup {...props} key={applyWith || 'bulk'} templates={usable} initialTemplate={applyWith} onDone={() => setMode('calendar')} />}
    </>;
}

// Calendar views -------------------------------------------------------------------------------

function CalendarViews({ display, members, today, name, member, inspect }: { display: R[]; members: R[]; today: string; name: (id: string) => string; member: (id: string) => string; inspect: (r: R) => void }) {
    const [layout, setLayout] = useState<'month' | 'week' | 'list'>('month'), [cursor, setCursor] = useState(today);
    const [category, setCategory] = useState('all'), [status, setStatus] = useState('all'), [person, setPerson] = useState('all'), [source, setSource] = useState('all'), [from, setFrom] = useState(''), [to, setTo] = useState('');
    const all = display.filter(r => CALENDAR_KINDS.includes(r.kind) && /^\d{4}-\d{2}-\d{2}$/.test(r.due || ''));
    const late = (r: R) => r.due < today && !SETTLED.includes(r.status);
    const items = all.filter(r => (status === 'all' ? r.status !== 'Cancelled' : status === 'overdue' ? late(r) : status === 'verify' ? unverified(r) && r.status !== 'Cancelled' : r.status === status)
        && (category === 'all' || categoryOf(r) === category) && (person === 'all' || (person === '' ? !r.assignee : r.assignee === person))
        && (source === 'all' || origin(r) === source) && (!from || r.due >= from) && (!to || r.due <= to)).sort((a, b) => a.due.localeCompare(b.due) || String(a.title).localeCompare(String(b.title)));
    const byDay = new Map<string, R[]>(); items.forEach(r => byDay.set(r.due, [...(byDay.get(r.due) || []), r]));
    const categories = Array.from(new Set(all.map(categoryOf))).sort(), statuses = Array.from(new Set(all.map(r => r.status).filter(Boolean))).sort();
    const people = members.filter(m => all.some(r => r.assignee === m.id));
    const anchor = new Date(cursor + 'T12:00:00'), weekStart = new Date(anchor); weekStart.setDate(anchor.getDate() - (anchor.getDay() + 6) % 7);
    const week = Array.from({ length: 7 }, (_, i) => { const d = new Date(weekStart); d.setDate(weekStart.getDate() + i); return d });
    const move = (n: number) => { const d = new Date(anchor); if (layout === 'week') d.setDate(d.getDate() + 7 * n); else { d.setDate(1); d.setMonth(d.getMonth() + n) } setCursor(iso(d)) };
    const heading = layout === 'month' ? anchor.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' }) : layout === 'week' ? `${week[0].toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} – ${week[6].toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}` : from || to ? `${from ? fmt(from) : 'Any date'} – ${to ? fmt(to) : 'any date'}` : 'All dates';
    const monthKey = cursor.slice(0, 7), shownNow = layout === 'month' ? items.filter(r => r.due.startsWith(monthKey)) : layout === 'week' ? items.filter(r => r.due >= iso(week[0]) && r.due <= iso(week[6])) : items;
    const filtered = category !== 'all' || status !== 'all' || person !== 'all' || source !== 'all' || !!from || !!to;
    const chip = (r: R) => <button key={r.id} className={'cal-chip ' + (r.template ? 'tpl' : r.rule ? 'rule' : 'other') + (late(r) ? ' late' : '') + (unverified(r) ? ' verify' : '')} onClick={() => inspect(r)} title={`${r.title} · ${name(r.company)} · ${r.status || 'Not started'}${unverified(r) ? ' · date to be verified' : ''}`}><span>{r.title}</span><small>{initials(name(r.company))}</small></button>;
    const showDay = (key: string) => { setFrom(key); setTo(key); setLayout('list') };
    const monthGrid = () => { const first = new Date(anchor.getFullYear(), anchor.getMonth(), 1), length = new Date(anchor.getFullYear(), anchor.getMonth() + 1, 0).getDate(); return <div className="calendar-scroll"><div className="month-grid">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div className="weekday" key={d}>{d}</div>)}{Array.from({ length: (first.getDay() + 6) % 7 }, (_, i) => <div key={'b' + i} className="day blank" />)}{Array.from({ length }, (_, i) => { const key = iso(new Date(anchor.getFullYear(), anchor.getMonth(), i + 1)), list = byDay.get(key) || []; return <div className={'day ' + (key === today ? 'today' : '')} key={key}><b>{i + 1}</b>{list.slice(0, 4).map(chip)}{list.length > 4 && <button className="cal-more" onClick={() => showDay(key)}>+{list.length - 4} more</button>}</div> })}</div></div> };
    const weekGrid = () => <div className="calendar-scroll"><div className="week-grid">{week.map(d => { const key = iso(d), list = byDay.get(key) || []; return <section className={'week-day ' + (key === today ? 'today' : '')} key={key}><header><small>{d.toLocaleDateString('en-GB', { weekday: 'short' })}</small><b>{d.getDate()} {MONTHS[d.getMonth()]}</b></header>{list.map(r => <button key={r.id} className={'week-entry ' + (r.template ? 'tpl' : r.rule ? 'rule' : 'other')} onClick={() => inspect(r)}><strong>{r.title}</strong><small>{name(r.company)}</small><span><Pill value={late(r) ? 'Overdue' : r.status || 'Not started'} />{unverified(r) && <Pill value="To be verified" />}</span><small>{member(r.assignee)}</small></button>)}{!list.length && <p className="muted">Nothing due</p>}</section> })}</div></div>;
    const listTable = () => { const shown = items.slice(0, 500); return <div className="data-scroll"><table className="records-table"><thead><tr><th>Due date</th><th>Entry</th><th>Company</th><th>Period</th><th>Responsible</th><th>Status</th><th>Date check</th></tr></thead><tbody>{shown.map(r => <tr key={r.id}><td><span className={late(r) ? 'overdue' : ''}>{fmt(r.due)}</span></td><td><button className="record-name" onClick={() => inspect(r)}>{r.title}</button><span className="record-meta">{categoryOf(r)} · {origin(r) === 'Template' ? 'Template: ' + r.template.name : origin(r) === 'Rule library' ? 'Rule Library obligation' : 'Created individually'}</span></td><td><span className="company-cell"><i>{initials(name(r.company))}</i>{name(r.company)}</span></td><td>{r.template?.periodLabel || r.period || '—'}</td><td><span className="person-cell"><i>{initials(member(r.assignee))}</i>{member(r.assignee)}</span></td><td><Pill value={late(r) ? 'Overdue' : r.status || 'Not started'} /></td><td>{r.template ? (unverified(r) ? <Pill value="To be verified" /> : <Pill value="Date verified" />) : <span className="muted">—</span>}</td></tr>)}</tbody></table>{items.length > shown.length && <p className="inline-note">Showing the first 500 of {items.length} entries. Narrow the date range or filters to see the rest.</p>}{!items.length && <Empty title="No calendar entries match" body={filtered ? 'Adjust or clear the filters.' : 'Set up a company’s calendar individually, or many companies at once with Bulk setup.'} />}</div> };
    return <section className="surface">
        <div className="section-head"><div><h2>{heading}</h2><p>{plural(shownNow.length, 'entry', 'entries')}{layout === 'month' ? ' this month' : layout === 'week' ? ' this week' : ''} · meetings, work deadlines and client requests for the companies you can access</p></div><div className="page-actions"><div className="segmented" role="group" aria-label="Calendar layout">{(['month', 'week', 'list'] as const).map(l => <button key={l} className={layout === l ? 'on' : ''} aria-pressed={layout === l} onClick={() => setLayout(l)}>{l === 'month' ? 'Month' : l === 'week' ? 'Week' : 'List'}</button>)}</div>{layout !== 'list' && <><button className="btn secondary" aria-label={'Previous ' + layout} onClick={() => move(-1)}><ChevronLeft size={15} /></button><button className="btn secondary" onClick={() => setCursor(today)}>Today</button><button className="btn secondary" aria-label={'Next ' + layout} onClick={() => move(1)}><ChevronRight size={15} /></button></>}</div></div>
        <div className="cal-filters">
            <label><span>Category</span><select aria-label="Category filter" value={category} onChange={e => setCategory(e.target.value)}><option value="all">All categories</option>{categories.map(c => <option key={c}>{c}</option>)}</select></label>
            <label><span>Status</span><select aria-label="Calendar status filter" value={status} onChange={e => setStatus(e.target.value)}><option value="all">All open and completed</option><option value="overdue">Overdue</option><option value="verify">Dates to verify</option>{statuses.map(s => <option key={s}>{s}</option>)}</select></label>
            <label><span>Responsible</span><select aria-label="Responsible person filter" value={person} onChange={e => setPerson(e.target.value)}><option value="all">Everyone</option>{people.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}<option value="">Unassigned</option></select></label>
            <label><span>Source</span><select aria-label="Source filter" value={source} onChange={e => setSource(e.target.value)}><option value="all">All sources</option><option value="Template">Calendar templates</option><option value="Rule library">Rule Library</option><option value="Individual">Created individually</option></select></label>
            <label><span>From</span><input type="date" aria-label="From date" value={from} onChange={e => setFrom(e.target.value)} /></label>
            <label><span>To</span><input type="date" aria-label="To date" value={to} onChange={e => setTo(e.target.value)} /></label>
            {filtered && <button className="text-btn" onClick={() => { setCategory('all'); setStatus('all'); setPerson('all'); setSource('all'); setFrom(''); setTo('') }}>Clear filters</button>}
        </div>
        <div className="cal-legend" aria-hidden="true"><span className="tpl">Template entry</span><span className="rule">Rule Library obligation</span><span className="other">Other work</span><span className="verify">Date to be verified</span></div>
        {layout === 'month' ? monthGrid() : layout === 'week' ? weekGrid() : listTable()}
    </section>;
}

// Templates ------------------------------------------------------------------------------------

function toDraft(t: R | null, today: string): Draft {
    if (!t) return { name: '', description: '', companyType: 'Private limited company', financialYear: fyOf(today), secretaryApply: false, activities: [blankActivity()] };
    return { id: t.id, revision: t.revision, name: t.name || '', description: t.description || '', companyType: t.companyType || '', financialYear: t.financialYear || fyOf(today), secretaryApply: t.secretaryApply === true, activities: (t.activities || []).map((a: any) => ({ ...blankActivity(), ...a, key: a.id || crypto.randomUUID(), dueDay: String(a.dueDay ?? ''), monthsAfter: String(a.monthsAfter ?? 0), reminders: a.reminders || { days: [], overdue: false } })) };
}

function TemplateManager({ templates, records, owner, canApply, onApply, today, member, reload, notify, audit }: { templates: R[]; records: R[]; owner: boolean; canApply: (t: R) => boolean; onApply: (t: R) => void; today: string; member: (id: string) => string; reload: () => Promise<any>; notify: (m: string) => void; audit: any[] }) {
    const [show, setShow] = useState<'Active' | 'Archived'>('Active'), [editing, setEditing] = useState<Draft | null>(null), [viewing, setViewing] = useState(''), [busy, setBusy] = useState(false), [error, setError] = useState(''), [archiving, setArchiving] = useState<R | null>(null);
    const entries = records.filter(r => r.kind === 'task' && r.template);
    const usage = (t: R) => { const mine = entries.filter(r => r.template.id === t.id); return { entries: mine.length, companies: new Set(mine.map(r => r.company)).size } };
    const shown = templates.filter(t => (t.status || 'Active') === show).sort((a, b) => String(a.name).localeCompare(String(b.name)));
    async function act(body: any, message: string) { setBusy(true); setError(''); try { const d = await post(body); await reload(); notify(message); return d } catch (e: any) { setError(e.message); return null } finally { setBusy(false) } }
    const current = templates.find(t => t.id === viewing);
    return <>
        <div className="context-note"><ShieldCheck size={18} /><span>A template lists the compliance activities you set up again and again. Saving or changing a template never creates or changes calendar entries: entries are only created by Bulk setup, after a preview, and every company’s entries stay independent. Due-date rules are proposals to verify per company, not authoritative statutory deadlines.</span></div>
        {error && !editing && !archiving && <div className="error-banner" role="alert"><AlertCircle size={18} />{error}<button onClick={() => setError('')} aria-label="Dismiss error"><X size={16} /></button></div>}
        <section className="surface">
            <div className="section-head"><div><h2>Compliance calendar templates</h2><p>{plural(templates.filter(t => t.status === 'Active').length, 'active template')}{templates.some(t => t.status === 'Archived') ? ' · ' + plural(templates.filter(t => t.status === 'Archived').length, 'archived') : ''}{owner ? '' : ' · templates are managed by the workspace owner'}</p></div><div className="page-actions"><div className="segmented" role="group" aria-label="Template status">{(['Active', 'Archived'] as const).map(s => <button key={s} className={show === s ? 'on' : ''} aria-pressed={show === s} onClick={() => setShow(s)}>{s}</button>)}</div>{owner && <button className="btn primary" onClick={() => { setError(''); setEditing(toDraft(null, today)) }}><Plus size={16} />New template</button>}</div></div>
            {shown.length ? <div className="tpl-grid">{shown.map(t => { const u = usage(t); return <article className="tpl-card" key={t.id}>
                <div className="tpl-card-head"><Pill value={t.status || 'Active'} />{t.secretaryApply && <span className="pill neutral">Secretaries may apply</span>}<small>Version {t.templateVersion || 1}</small></div>
                <h3>{t.name}</h3><p>{t.description || 'No description'}</p>
                <dl><div><dt>Company type</dt><dd>{t.companyType || 'Any company type'}</dd></div><div><dt>Financial year</dt><dd>{t.financialYear}</dd></div><div><dt>Activities</dt><dd>{(t.activities || []).length}</dd></div><div><dt>Used for</dt><dd>{u.entries ? `${plural(u.entries, 'entry', 'entries')} · ${plural(u.companies, 'company', 'companies')}` : 'Not applied yet'}</dd></div></dl>
                <ul className="tpl-activities">{(t.activities || []).slice(0, 4).map((a: any) => <li key={a.id}><span>{a.name}</span><small>{a.frequency}</small></li>)}{(t.activities || []).length > 4 && <li><small>+{t.activities.length - 4} more</small></li>}</ul>
                <footer><button className="text-btn" onClick={() => setViewing(t.id)}><Eye size={15} />View</button>{owner && t.status !== 'Archived' && <button className="text-btn" onClick={() => { setError(''); setEditing(toDraft(t, today)) }}><Pencil size={15} />Edit</button>}{owner && <button className="text-btn" disabled={busy} onClick={() => act({ action: 'templateDuplicate', id: t.id, revision: t.revision }, 'Template duplicated · review and rename the copy')}><Copy size={15} />Duplicate</button>}{owner && (t.status === 'Archived' ? <button className="text-btn" disabled={busy} onClick={() => act({ action: 'templateArchive', id: t.id, revision: t.revision, archived: false }, 'Template restored')}><RotateCcw size={15} />Restore</button> : <button className="text-btn" disabled={busy} onClick={() => { setError(''); setArchiving(t) }}><Archive size={15} />Archive</button>)}<div />{canApply(t) && <button className="btn primary" onClick={() => onApply(t)}><Layers size={15} />Apply</button>}</footer>
            </article> })}</div> : <Empty title={show === 'Active' ? 'No templates yet' : 'No archived templates'} body={show === 'Active' ? (owner ? 'Create a template once, then apply it to as many companies as you need.' : 'The workspace owner creates the templates used for bulk calendar setup.') : 'Archived templates appear here. Their generated entries are not affected.'} action={owner && show === 'Active' ? <button className="btn primary" onClick={() => setEditing(toDraft(null, today))}><Plus size={16} />New template</button> : undefined} />}
        </section>
        {editing && <TemplateEditor draft={editing} setDraft={setEditing} busy={busy} error={error} onClose={() => { if (!busy) { setEditing(null); setError('') } }} onSave={async () => {
            const data = { name: editing.name, description: editing.description, companyType: editing.companyType, financialYear: editing.financialYear, secretaryApply: editing.secretaryApply, activities: editing.activities.map(payload) };
            const done = await act(editing.id ? { action: 'templateSave', id: editing.id, revision: editing.revision, data } : { action: 'templateCreate', data }, editing.id ? 'Template saved as a new version · existing entries are unchanged' : 'Template created · no calendar entries were created');
            if (done) setEditing(null);
        }} />}
        {current && <Dialog overline="CALENDAR TEMPLATE" title={current.name} wide onClose={() => setViewing('')} footer={<><button className="btn secondary" onClick={() => setViewing('')}>Close</button><div />{owner && current.status !== 'Archived' && <button className="btn secondary" onClick={() => { setViewing(''); setEditing(toDraft(current, today)) }}><Pencil size={15} />Edit</button>}{canApply(current) && <button className="btn primary" onClick={() => { setViewing(''); onApply(current) }}><Layers size={15} />Apply to companies</button>}</>}>
            <div className="drawer-content">
                <p className="muted">{current.description || 'No description'}</p>
                <dl className="record-facts"><div><dt>Status</dt><dd>{current.status} · version {current.templateVersion || 1}</dd></div><div><dt>Applies to</dt><dd>{current.companyType || 'Any company type'}</dd></div><div><dt>Default financial year</dt><dd>{current.financialYear} (April – March)</dd></div><div><dt>Secretaries</dt><dd>{current.secretaryApply ? 'May apply this template' : 'Owner applies only'}</dd></div><div><dt>Created</dt><dd>{member(current.createdBy)}{current.createdAt ? ' · ' + new Date(current.createdAt).toLocaleString() : ''}</dd></div><div><dt>Last changed</dt><dd>{member(current.updatedBy)}{current.updatedAt ? ' · ' + new Date(current.updatedAt).toLocaleString() : ''}</dd></div>{current.duplicatedFrom && <div><dt>Copied from</dt><dd>{current.duplicatedFrom.name} (version {current.duplicatedFrom.version})</dd></div>}{current.archivedAt && <div><dt>Archived</dt><dd>{member(current.archivedBy)} · {new Date(current.archivedAt).toLocaleString()}</dd></div>}</dl>
                <h3>Compliance activities</h3>
                <div className="data-scroll"><table className="records-table"><thead><tr><th>Activity</th><th>Frequency and due date</th><th>Responsible</th><th>Reminders</th><th>Date check</th></tr></thead><tbody>{(current.activities || []).map((a: any) => <tr key={a.id}><td><strong>{a.name}</strong><span className="record-meta">{a.category}{a.filing ? ' · external filing' : ''}{a.clientVisible ? ' · on client calendar' : ''}</span></td><td>{a.frequency} · day {a.dueDay}{a.monthsAfter ? `, ${plural(a.monthsAfter, 'month')} after the period` : ', in the period’s last month'}<span className="record-meta">{example({ ...a, dueDay: String(a.dueDay), monthsAfter: String(a.monthsAfter), key: a.id }, current.financialYear)}</span></td><td>{a.role}</td><td>{reminderText(a.reminders)}</td><td>{a.verifyDates ? 'Verify per company' : 'Internal deadline'}{a.dateBasis && <span className="record-meta">{a.dateBasis}</span>}</td></tr>)}</tbody></table></div>
                {(current.activities || []).some((a: any) => a.instructions) && <><h3 className="tpl-subhead">Preparation instructions</h3>{current.activities.filter((a: any) => a.instructions).map((a: any) => <div className="inline-note tpl-instructions" key={a.id}><strong>{a.name}</strong><p>{a.instructions}</p></div>)}</>}
                <h3 className="tpl-subhead">History</h3><div className="timeline">{audit.filter((a: any) => a.subject === current.name || String(a.subject).startsWith(current.name + ' ') || String(a.subject).includes('→ ' + current.name)).slice(0, 12).map((a: any) => <div key={a.id}><i><Check size={14} /></i><div><strong>{a.action}</strong><p>{a.subject}</p><small>{new Date(a.at).toLocaleString()}</small></div></div>)}</div>
            </div>
        </Dialog>}
        {archiving && <Dialog overline="ARCHIVE TEMPLATE" title={`Archive “${archiving.name}”?`} busy={busy} onClose={() => setArchiving(null)} footer={<><button className="btn secondary" disabled={busy} onClick={() => setArchiving(null)}>Keep it active</button><button className="btn primary" disabled={busy} onClick={async () => { if (await act({ action: 'templateArchive', id: archiving.id, revision: archiving.revision, archived: true }, 'Template archived · its entries are unchanged')) setArchiving(null) }}>{busy ? 'Archiving…' : 'Archive template'}</button></>}>
            <div className="drawer-content">{error && <div className="error-banner" role="alert">{error}</div>}<div className="context-note"><Archive size={18} /><span>An archived template can no longer be applied. {usage(archiving).entries ? `The ${plural(usage(archiving).entries, 'entry', 'entries')} already created from it stay exactly as they are and keep their link to it.` : 'It has not been applied to any company yet.'} You can restore it at any time.</span></div></div>
        </Dialog>}
    </>;
}

/** An activity as the server expects it: numbers for the due-date rule, without the editor's row key. */
function payload(a: Activity) { const rest: Partial<Activity> = { ...a }; delete rest.key; return { ...rest, dueDay: Number(a.dueDay), monthsAfter: Number(a.monthsAfter) } }

function TemplateEditor({ draft, setDraft, busy, error, onClose, onSave }: { draft: Draft; setDraft: (d: Draft) => void; busy: boolean; error: string; onClose: () => void; onSave: () => void }) {
    const fy = fyOf(new Date().toISOString().slice(0, 10)), years = [-1, 0, 1, 2].map(n => shiftFy(fy, n));
    if (!years.includes(draft.financialYear)) years.unshift(draft.financialYear);
    const set = (patch: Partial<Draft>) => setDraft({ ...draft, ...patch });
    const setActivity = (key: string, patch: Partial<Activity>) => set({ activities: draft.activities.map(a => a.key === key ? { ...a, ...patch } : a) });
    const empty = draft.activities.every(a => !a.name.trim());
    return <Dialog overline={draft.id ? 'EDIT TEMPLATE' : 'NEW TEMPLATE'} title={draft.id ? draft.name || 'Edit template' : 'Create a compliance calendar template'} wide busy={busy} onClose={onClose} footer={<><button className="btn secondary" type="button" disabled={busy} onClick={onClose}>Cancel</button><div /><button className="btn primary" type="submit" form="template-form" disabled={busy}>{busy ? 'Saving…' : draft.id ? 'Save as new version' : 'Create template'}</button></>}>
        <form id="template-form" onSubmit={e => { e.preventDefault(); onSave() }}><div className="drawer-content">
            {error && <div className="error-banner" role="alert">{error}</div>}
            {draft.id && <div className="context-note"><AlertCircle size={18} /><span>Saving creates the next version of this template. Entries created from earlier versions are not changed; applying the template again skips periods that already have an entry.</span></div>}
            <label className="field"><span>Template name <em>*</em></span><input required maxLength={200} value={draft.name} placeholder="e.g. Standard Private Limited Company – FY 2026-27" onChange={e => set({ name: e.target.value })} /></label>
            <label className="field"><span>Description</span><textarea rows={2} maxLength={2000} value={draft.description} onChange={e => set({ description: e.target.value })} /></label>
            <div className="form-grid"><label className="field"><span>Applicable company type</span><select value={draft.companyType} onChange={e => set({ companyType: e.target.value })}><option value="">Any company type</option>{COMPANY_TYPES.map(t => <option key={t}>{t}</option>)}</select></label><label className="field"><span>Default financial year</span><select value={draft.financialYear} onChange={e => set({ financialYear: e.target.value })}>{years.map(y => <option key={y} value={y}>{y} (April – March)</option>)}</select></label></div>
            <label className="check-row"><input type="checkbox" checked={draft.secretaryApply} onChange={e => set({ secretaryApply: e.target.checked })} /><span>Secretaries may apply this template<small>Without this, only the workspace owner can run bulk setup with it.</small></span></label>
            <section className="form-section"><div className="tpl-editor-head"><div><h3>Compliance activities</h3><p className="muted">Each activity becomes one entry per period for every company it is applied to.</p></div>{!draft.id && empty && <button type="button" className="btn secondary" onClick={() => set({ activities: exampleActivities() })}>Start from the example</button>}</div>
                {draft.activities.map((a, i) => <fieldset className="tpl-activity" key={a.key}><legend>Activity {i + 1}</legend>
                    <div className="form-grid"><label className="field"><span>Compliance activity name <em>*</em></span><input required maxLength={200} value={a.name} onChange={e => setActivity(a.key, { name: e.target.value })} /></label><label className="field"><span>Compliance category</span><input maxLength={120} value={a.category} placeholder="e.g. GST" onChange={e => setActivity(a.key, { category: e.target.value })} /></label></div>
                    <div className="tpl-rule"><label className="field"><span>Frequency</span><select value={a.frequency} onChange={e => setActivity(a.key, { frequency: e.target.value })}>{FREQUENCIES.map(f => <option key={f}>{f}</option>)}</select></label><label className="field"><span>Due day of month</span><input type="number" min={1} max={31} required value={a.dueDay} onChange={e => setActivity(a.key, { dueDay: e.target.value })} /></label><label className="field"><span>Months after the period ends</span><input type="number" min={0} max={12} required value={a.monthsAfter} onChange={e => setActivity(a.key, { monthsAfter: e.target.value })} /></label><label className="field"><span>Responsible role</span><select value={a.role} onChange={e => setActivity(a.key, { role: e.target.value })}>{ROLES.map(r => <option key={r}>{r}</option>)}</select></label></div>
                    <p className="field-hint">Due date rule · {example(a, draft.financialYear)}. Day 31 becomes the last day of shorter months.</p>
                    <label className="field"><span>Deadline basis / source to verify</span><input maxLength={500} value={a.dateBasis} placeholder="e.g. Verify against the applicable notification for each period" onChange={e => setActivity(a.key, { dateBasis: e.target.value })} /></label>
                    <div className="reminder-checks" role="group" aria-label={'Reminders for activity ' + (i + 1)}><span>Reminders</span>{REMINDER_DAYS.map(d => <label key={d}><input type="checkbox" checked={a.reminders.days.includes(d)} onChange={e => setActivity(a.key, { reminders: { ...a.reminders, days: e.target.checked ? [...a.reminders.days, d].sort((x, y) => y - x) : a.reminders.days.filter(x => x !== d) } })} />{d ? `${d} day${d === 1 ? '' : 's'} before` : 'On the due date'}</label>)}<label><input type="checkbox" checked={a.reminders.overdue} onChange={e => setActivity(a.key, { reminders: { ...a.reminders, overdue: e.target.checked } })} />When overdue</label></div>
                    <label className="field"><span>Preparation instructions</span><textarea rows={2} maxLength={4000} value={a.instructions} onChange={e => setActivity(a.key, { instructions: e.target.value })} /></label>
                    <div className="tpl-flags"><label className="check-row"><input type="checkbox" checked={a.verifyDates} onChange={e => setActivity(a.key, { verifyDates: e.target.checked })} />Each company’s date must be verified</label><label className="check-row"><input type="checkbox" checked={a.filing} onChange={e => setActivity(a.key, { filing: e.target.checked })} />External filing required</label><label className="check-row"><input type="checkbox" checked={a.clientVisible} onChange={e => setActivity(a.key, { clientVisible: e.target.checked })} />Show on the client portal calendar</label>{draft.activities.length > 1 && <button type="button" className="text-btn danger-text" onClick={() => set({ activities: draft.activities.filter(x => x.key !== a.key) })}><X size={14} />Remove activity</button>}</div>
                </fieldset>)}
                <button type="button" className="text-btn" onClick={() => set({ activities: [...draft.activities, blankActivity()] })}><Plus size={15} />Add compliance activity</button>
            </section>
        </div></form>
    </Dialog>;
}

// Bulk setup -----------------------------------------------------------------------------------

function BulkSetup({ templates, companies, records, today, initialTemplate, name, member, reload, notify, onDone }: { templates: R[]; companies: R[]; records: R[]; today: string; initialTemplate: string; name: (id: string) => string; member: (id: string) => string; reload: () => Promise<any>; notify: (m: string) => void; onDone: () => void }) {
    const [step, setStep] = useState(initialTemplate && templates.some(t => t.id === initialTemplate) ? 2 : 1), [templateId, setTemplateId] = useState(templates.some(t => t.id === initialTemplate) ? initialTemplate : '');
    const template = templates.find(t => t.id === templateId);
    const [fy, setFy] = useState(template?.financialYear || fyOf(today)), [includePast, setIncludePast] = useState(false);
    const [selected, setSelected] = useState<string[]>([]), [search, setSearch] = useState(''), [typeFilter, setTypeFilter] = useState('all'), [statusFilter, setStatusFilter] = useState('active');
    const [activities, setActivities] = useState<string[] | null>(null), [assignments, setAssignments] = useState<Record<string, Record<string, string>>>({});
    const [dates, setDates] = useState<Record<string, Record<string, string>>>({}), [confirmed, setConfirmed] = useState<Record<string, string[]>>({}), [excluded, setExcluded] = useState<Record<string, string[]>>({});
    const [plan, setPlan] = useState<any>(null), [planError, setPlanError] = useState(''), [loading, setLoading] = useState(false), [open, setOpen] = useState<string[]>([]);
    const [confirming, setConfirming] = useState(false), [progress, setProgress] = useState<{ done: number; total: number; current: string } | null>(null), [results, setResults] = useState<Result[] | null>(null), [run, setRun] = useState('');
    const latest = useRef(0);
    const typeOf = (c: R) => c.entityType || '';
    const eligibility = (c: R) => c.inactive === true ? 'Inactive company' : template?.companyType && typeOf(c) && typeOf(c) !== template.companyType ? `Company type is ${typeOf(c)}` : '';
    const types = Array.from(new Set(companies.map(typeOf))).sort();
    const visible = companies.filter(c => (!search || String(c.name).toLowerCase().includes(search.toLowerCase())) && (typeFilter === 'all' || typeOf(c) === typeFilter) && (statusFilter === 'all' || (statusFilter === 'active') === (c.inactive !== true))).sort((a, b) => String(a.name).localeCompare(String(b.name)));
    const config = () => ({ template: templateId, companies: selected, financialYear: fy, includePast, ...(activities ? { activities } : {}), assignments, dates, confirmed, excluded });
    const batches = records.filter(r => r.kind === 'calendarbatch').sort((a, b) => String(b.initiatedAt).localeCompare(String(a.initiatedAt))).slice(0, 8);

    // The plan always comes from the server, refreshed (debounced) whenever a choice changes.
    const previewBody = JSON.stringify({ action: 'calendarPreview', ...config() }), wantsPlan = step >= 3 && !!templateId && selected.length > 0 && !results;
    useEffect(() => {
        if (!wantsPlan) return;
        const ticket = ++latest.current;
        const timer = setTimeout(async () => { setLoading(true); try { const d = await post(JSON.parse(previewBody)); if (ticket === latest.current) { setPlan(d); setPlanError('') } } catch (e: any) { if (ticket === latest.current) setPlanError(e.message) } finally { if (ticket === latest.current) setLoading(false) } }, 250);
        return () => clearTimeout(timer);
    }, [wantsPlan, previewBody]);

    function pickTemplate(id: string) { const t = templates.find(x => x.id === id); setTemplateId(id); setFy(t?.financialYear || fyOf(today)); setActivities(null); setPlan(null); setDates({}); setConfirmed({}); setExcluded({}); setSelected(s => s.filter(c => { const company = companies.find(x => x.id === c); return company && !(company.inactive === true || (t?.companyType && company.entityType && company.entityType !== t.companyType)) })) }
    const toggle = (cid: string, on: boolean) => setSelected(s => on ? Array.from(new Set([...s, cid])) : s.filter(x => x !== cid));
    const keysOf = (state: Record<string, string[]>, cid: string) => state[cid] || [];
    const setKey = (state: Record<string, string[]>, setter: (v: Record<string, string[]>) => void, cid: string, key: string, on: boolean) => setter({ ...state, [cid]: on ? Array.from(new Set([...keysOf(state, cid), key])) : keysOf(state, cid).filter(k => k !== key) });
    const eligibleIds = () => (plan?.companies || []).filter((c: any) => c.eligible).map((c: any) => c.id);

    async function createAll(targets: string[], runId: string, previous: Result[] = []) {
        setConfirming(false); setResults(null);
        const out: Result[] = previous.filter(r => !targets.includes(r.company));
        for (let i = 0; i < targets.length; i++) {
            const cid = targets[i]; setProgress({ done: i, total: targets.length, current: name(cid) });
            try { const d = await post({ action: 'calendarApply', ...config(), companies: [cid], selection: eligibleIds(), run: runId, templateVersion: plan.template.version }); out.push(...d.results) }
            catch (e: any) { out.push({ company: cid, name: name(cid), status: 'Failed', created: 0, existing: 0, duplicates: 0, ruleCovered: 0, excluded: 0, past: 0, needsConfirmation: 0, error: e.message || 'The request did not complete.' }) }
        }
        setProgress({ done: targets.length, total: targets.length, current: '' });
        const order = eligibleIds(); out.sort((a, b) => order.indexOf(a.company) - order.indexOf(b.company));
        setResults(out); setProgress(null); setStep(5);
        try { await reload() } catch { /* the results above are what was saved; the workspace refreshes on the next load */ }
        const made = out.reduce((n, r) => n + r.created, 0), failed = out.filter(r => r.status === 'Failed').length;
        notify(failed ? `${made} entries created · ${failed} compan${failed === 1 ? 'y' : 'ies'} failed` : `${made} calendar entries created for ${plural(out.length, 'company', 'companies')}`);
    }
    const steps = ['Template', 'Companies', 'Settings', 'Preview', 'Result'];
    const s = plan?.summary, stepOk = step === 1 ? !!template : step === 2 ? selected.length > 0 : true;
    return <>
        <ol className="wizard-steps" aria-label="Bulk setup steps">{steps.map((label, i) => <li key={label} className={(step === i + 1 ? 'current ' : '') + (step > i + 1 ? 'done' : '')} aria-current={step === i + 1 ? 'step' : undefined}><span>{step > i + 1 ? <Check size={13} /> : i + 1}</span>{label}</li>)}</ol>
        {step === 1 && <>
            <section className="surface"><div className="section-head"><div><h2>Choose a template</h2><p>Templates are reusable: applying one creates entries only after you review the preview.</p></div></div>
                {templates.length ? <div className="tpl-grid">{templates.map(t => <button type="button" key={t.id} className={'tpl-card pick ' + (templateId === t.id ? 'selected' : '')} aria-pressed={templateId === t.id} onClick={() => pickTemplate(t.id)}><div className="tpl-card-head"><Pill value="Active" /><small>Version {t.templateVersion || 1}</small>{templateId === t.id && <CheckCircle2 size={18} />}</div><h3>{t.name}</h3><p>{t.description || 'No description'}</p><dl><div><dt>Company type</dt><dd>{t.companyType || 'Any company type'}</dd></div><div><dt>Activities</dt><dd>{(t.activities || []).length}</dd></div></dl></button>)}</div> : <Empty title="No template available" body="Create a template in Manage templates first." />}
                {template && <div className="bulk-options"><label className="field"><span>Financial year</span><select value={fy} onChange={e => setFy(e.target.value)}>{Array.from(new Set([-1, 0, 1, 2].map(n => shiftFy(fyOf(today), n)).concat(template.financialYear))).sort().map(y => <option key={y} value={y}>{y} (1 Apr {y.slice(0, 4)} – 31 Mar {+y.slice(0, 4) + 1}){y === template.financialYear ? ' · template default' : ''}</option>)}</select></label><label className="check-row"><input type="checkbox" checked={includePast} onChange={e => setIncludePast(e.target.checked)} /><span>Include periods whose due date has already passed<small>Off by default, so a mid-year setup does not create work that is already overdue.</small></span></label></div>}
            </section>
            {batches.length > 0 && <section className="surface"><div className="section-head"><div><h2>Recent bulk runs</h2><p>Each run is logged with who started it and every company’s outcome. Running a template again safely skips entries that already exist.</p></div></div><div className="data-scroll"><table className="records-table"><thead><tr><th>Run</th><th>Started</th><th>Companies</th><th>Entries created</th><th>Status</th></tr></thead><tbody>{batches.map(b => { const res: any[] = Object.values(b.results || {}); return <tr key={b.id}><td><strong>{b.template?.name}</strong><span className="record-meta">Version {b.template?.version} · FY {b.financialYear}</span></td><td>{b.initiatedByName || member(b.initiatedBy)}<span className="record-meta">{b.initiatedAt ? new Date(b.initiatedAt).toLocaleString() : ''}</span></td><td>{(b.selection || []).length}{res.some(r => r.status === 'Failed') && <span className="record-meta">Failed: {res.filter(r => r.status === 'Failed').map(r => r.name).join(', ')}</span>}</td><td>{res.reduce((n, r) => n + (r.createdTotal || 0), 0)}</td><td><Pill value={b.status === 'In progress' ? 'In progress run' : b.status} /></td></tr> })}</tbody></table></div></section>}
        </>}
        {step === 2 && <section className="surface">
            <div className="section-head"><div><h2>Select companies</h2><p>{plural(selected.length, 'company', 'companies')} selected · {template?.companyType ? `this template is for ${template.companyType}` : 'this template applies to any company type'}</p></div><div className="page-actions"><button className="btn secondary" onClick={() => setSelected(s => Array.from(new Set([...s, ...visible.filter(c => !eligibility(c)).map(c => c.id)])))}>Select all eligible{search || typeFilter !== 'all' || statusFilter !== 'all' ? ' shown' : ''}</button><button className="btn secondary" disabled={!selected.length} onClick={() => setSelected([])}>Clear selection</button></div></div>
            <div className="cal-filters"><label className="search-field"><Search size={16} /><input aria-label="Search companies" placeholder="Search companies by name…" value={search} onChange={e => setSearch(e.target.value)} /></label><label><span>Company type</span><select aria-label="Company type filter" value={typeFilter} onChange={e => setTypeFilter(e.target.value)}><option value="all">All company types</option>{types.map(t => <option key={t} value={t}>{t || 'Type not recorded'}</option>)}</select></label><label><span>Status</span><select aria-label="Company status filter" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}><option value="active">Active</option><option value="inactive">Inactive</option><option value="all">Active and inactive</option></select></label></div>
            <div className="data-scroll"><table className="records-table company-pick"><thead><tr><th><span className="sr-only">Select</span></th><th>Company</th><th>Company type</th><th>Status</th><th>Selection</th></tr></thead><tbody>{visible.map(c => { const why = eligibility(c), on = selected.includes(c.id); return <tr key={c.id} className={on ? 'picked' : why ? 'ineligible' : ''}><td><input type="checkbox" aria-label={'Select ' + c.name} checked={on} disabled={!!why && !on} onChange={e => toggle(c.id, e.target.checked)} /></td><td><span className="company-cell"><i>{initials(c.name)}</i>{c.name}</span></td><td>{typeOf(c) || <span className="muted">Not recorded</span>}</td><td><Pill value={c.inactive ? 'Inactive' : 'Active'} /></td><td>{why ? <span className="muted">Not eligible · {why}</span> : on ? <Pill value="Selected" /> : <span className="muted">Not selected</span>}</td></tr> })}</tbody></table>{!visible.length && <Empty title="No companies match" body="Change the search or filters." />}</div>
        </section>}
        {step >= 3 && step <= 4 && planError && <div className="error-banner" role="alert"><AlertCircle size={18} />{planError}</div>}
        {step === 3 && <section className="surface">
            <div className="section-head"><div><h2>Settings</h2><p>Choose the activities to apply and who is responsible at each company. Defaults use a team member with the activity’s role.</p></div>{loading && <span className="muted"><Loader2 size={15} className="spin" /> Updating…</span>}</div>
            <div className="drawer-content bulk-settings">
                <h3>Compliance activities</h3>
                <div className="data-scroll"><table className="records-table"><thead><tr><th>Include</th><th>Activity</th><th>Due date rule</th><th>Role</th><th>Date check</th></tr></thead><tbody>{(plan?.activities || (template?.activities || []).map((a: any) => ({ ...a, included: true }))).map((a: any) => { const on = activities ? activities.includes(a.id) : true; return <tr key={a.id}><td><input type="checkbox" aria-label={'Include ' + a.name} checked={on} onChange={e => { const all = (template?.activities || []).map((x: any) => x.id), now = activities || all; setActivities(e.target.checked ? all.filter((x: string) => now.includes(x) || x === a.id) : now.filter((x: string) => x !== a.id)) }} /></td><td><strong>{a.name}</strong><span className="record-meta">{a.category}{a.clientVisible ? ' · shown on client calendar' : ''}</span></td><td>{a.rule || a.frequency}</td><td>{a.role}</td><td>{a.verifyDates ? 'Verify per company' : 'Internal deadline'}</td></tr> })}</tbody></table></div>
                <h3>Responsible people</h3>
                {plan ? <div className="data-scroll"><table className="records-table"><thead><tr><th>Company</th>{Array.from(new Set((plan.activities || []).filter((a: any) => a.included).map((a: any) => a.role))).map((role: any) => <th key={role}>{role} activities</th>)}</tr></thead><tbody>{plan.companies.filter((c: any) => c.eligible).map((c: any) => <tr key={c.id}><td><span className="company-cell"><i>{initials(c.name)}</i>{c.name}</span>{c.assignmentErrors.map((p: string) => <span className="record-meta danger-text" key={p}>{p}</span>)}</td>{Object.keys(c.assignments).map(role => <td key={role}><select aria-label={`${role} responsible at ${c.name}`} value={assignments[c.id]?.[role] ?? c.assignments[role]} onChange={e => setAssignments({ ...assignments, [c.id]: { ...(assignments[c.id] || {}), [role]: e.target.value } })}><option value="">Unassigned</option>{c.assignable.map((m: any) => <option key={m.id} value={m.id}>{m.name}</option>)}{c.assignments[role] && !c.assignable.some((m: any) => m.id === c.assignments[role]) && <option value={c.assignments[role]}>{member(c.assignments[role])} (no access)</option>}</select></td>)}</tr>)}</tbody></table>{plan.companies.some((c: any) => !c.eligible) && <p className="inline-note">{plural(plan.companies.filter((c: any) => !c.eligible).length, 'selected company is', 'selected companies are')} not eligible and will be skipped: {plan.companies.filter((c: any) => !c.eligible).map((c: any) => `${c.name} (${c.reason})`).join('; ')}.</p>}</div> : <p className="muted">{loading ? 'Loading the plan…' : 'Select companies first.'}</p>}
            </div>
        </section>}
        {step === 4 && plan && <>
            <div className="metric-grid preview-summary">
                <div className="metric"><span>Selected companies</span><strong>{s.companies}</strong><small>{s.eligibleCompanies === s.companies ? 'All eligible' : `${s.eligibleCompanies} eligible`}</small></div>
                <div className="metric"><span>Template</span><strong className="metric-text">{s.template}</strong><small>Version {s.templateVersion} · FY {plan.financialYear}</small></div>
                <div className="metric"><span>Compliance activities</span><strong>{s.activities}</strong><small>of {s.activitiesTotal} in the template</small></div>
                <div className="metric"><span>Total calendar entries</span><strong>{s.entries}</strong><small>{s.excluded + s.past ? `${s.excluded} excluded · ${s.past} past due` : 'For the selected periods'}</small></div>
                <div className="metric"><span>Existing entries</span><strong>{s.existing}</strong><small>Already created from this template</small></div>
                <div className="metric"><span>Duplicates skipped</span><strong>{s.duplicates}</strong><small>{s.ruleCovered ? `${s.ruleCovered} covered by the Rule Library` : 'Equivalent work already scheduled'}</small></div>
                <div className="metric accent"><span>New entries to create</span><strong>{s.new}</strong><small>One independent entry per company and period</small></div>
                <div className="metric"><span>Dates to verify</span><strong>{s.needsConfirmation}</strong><small>Created as “to be verified” unless confirmed</small></div>
            </div>
            <div className="context-note"><AlertCircle size={18} /><span>Template dates are proposals. Statutory deadlines can depend on company type, financial year, filing period and each company’s circumstances: check them, change any company’s date below, and tick “Verified” only for dates you have checked. Unverified entries are flagged in the calendar until someone confirms them.</span></div>
            <section className="surface">
                <div className="section-head"><div><h2>Company-specific preview</h2><p>{loading ? 'Updating the preview…' : 'Open a company to review, change, verify or exclude its entries.'}</p></div><div className="page-actions"><button className="btn secondary" onClick={() => setOpen(open.length ? [] : plan.companies.map((c: any) => c.id))}>{open.length ? 'Collapse all' : 'Expand all'}</button></div></div>
                {plan.companies.map((c: any) => { const isOpen = open.includes(c.id) || plan.companies.length === 1; return <div className={'preview-company ' + (c.eligible ? '' : 'ineligible')} key={c.id}>
                    <button type="button" className="preview-company-head" aria-expanded={isOpen} onClick={() => setOpen(isOpen ? open.filter(x => x !== c.id) : [...open, c.id])}><ChevronRight size={16} className={isOpen ? 'turned' : ''} /><span className="company-cell"><i>{initials(c.name)}</i>{c.name}</span><small>{c.type || 'Type not recorded'}</small>{c.eligible ? <span className="preview-counts"><Pill value={`${c.counts.new} new`} />{c.counts.existing > 0 && <Pill value={`${c.counts.existing} existing`} />}{c.counts.duplicates > 0 && <Pill value={`${c.counts.duplicates} duplicates`} />}{c.counts.needsConfirmation > 0 && <Pill value={`${c.counts.needsConfirmation} to verify`} />}</span> : <Pill value="Not eligible" />}</button>
                    {(c.warnings.length > 0 || c.assignmentErrors.length > 0 || !c.eligible) && <div className="preview-warnings">{!c.eligible && <p><AlertCircle size={14} />{c.reason}: no entries will be created for this company.</p>}{[...c.assignmentErrors, ...c.warnings].map((w: string) => <p key={w}><AlertCircle size={14} />{w}</p>)}</div>}
                    {isOpen && c.eligible && <div className="data-scroll"><div className="preview-tools"><button type="button" className="text-btn" onClick={() => setConfirmed({ ...confirmed, [c.id]: Array.from(new Set([...keysOf(confirmed, c.id), ...c.entries.filter((e: any) => e.status === 'new' && e.verify).map((e: any) => e.key)])) })}><Check size={14} />Mark all of {c.name}’s new dates as verified</button></div><table className="records-table preview-table"><thead><tr><th>Include</th><th>Compliance</th><th>Period</th><th>Due date</th><th>Verified</th><th>Responsible</th><th>Status</th></tr></thead><tbody>{c.entries.map((e: any) => { const editable = ['new', 'past', 'excluded'].includes(e.status), mine = dates[c.id]?.[e.key]; return <tr key={e.key} className={e.status === 'new' ? '' : 'skipped'}><td>{editable ? <input type="checkbox" aria-label={`Include ${e.title} ${e.periodLabel} for ${c.name}`} checked={!keysOf(excluded, c.id).includes(e.key)} onChange={ev => setKey(excluded, setExcluded, c.id, e.key, !ev.target.checked)} /> : null}</td><td><strong>{e.title}</strong><span className="record-meta">{e.category}</span></td><td>{e.periodLabel}</td><td><input type="date" className="preview-date" aria-label={`Due date for ${e.title} ${e.periodLabel} at ${c.name}`} value={mine || e.due} disabled={!editable} onChange={ev => { const v = ev.target.value; setDates({ ...dates, [c.id]: { ...(dates[c.id] || {}), [e.key]: v } }); if (v && v !== e.generatedDue && e.verify) setKey(confirmed, setConfirmed, c.id, e.key, true) }} />{(e.adjusted || (mine && mine !== e.generatedDue)) && <span className="record-meta">Template date {fmt(e.generatedDue)} · <button type="button" className="link-btn" onClick={() => { const next = { ...(dates[c.id] || {}) }; delete next[e.key]; setDates({ ...dates, [c.id]: next }) }}>reset</button></span>}</td><td>{e.verify ? <input type="checkbox" aria-label={`Verified date for ${e.title} ${e.periodLabel} at ${c.name}`} checked={keysOf(confirmed, c.id).includes(e.key)} disabled={e.status !== 'new'} onChange={ev => setKey(confirmed, setConfirmed, c.id, e.key, ev.target.checked)} /> : <span className="muted">Internal</span>}</td><td>{e.assignee ? member(e.assignee) : <span className="muted">Unassigned</span>}</td><td><Pill value={ENTRY_STATUS[e.status]} />{e.reason && <span className="record-meta">{e.reason}</span>}</td></tr> })}</tbody></table></div>}
                </div> })}
            </section>
        </>}
        {step === 5 && results && (() => { const made = results.reduce((n, r) => n + r.created, 0), failed = results.filter(r => r.status === 'Failed'); return <section className="surface">
            <div className="section-head"><div><h2>{failed.length ? (failed.length === results.length ? 'Calendars were not created' : 'Calendars created with failures') : 'Calendars created'}</h2><p>{made} new {made === 1 ? 'entry' : 'entries'} · {plural(results.filter(r => r.status === 'Completed').length, 'company', 'companies')} completed{failed.length ? ` · ${failed.length} failed` : ''}. Every company’s entries are independent tasks you can manage individually.</p></div><Pill value={failed.length ? (failed.length === results.length ? 'Failed' : 'Partially failed') : 'Completed'} /></div>
            {failed.length > 0 && <div className="context-note"><AlertCircle size={18} /><span>Nothing was created for a failed company, and retrying is safe: entries that already exist are skipped, never duplicated. Fix the cause shown below (for example a responsible person without access) in the preview, then create again.</span></div>}
            <div className="data-scroll"><table className="records-table"><thead><tr><th>Company</th><th>Result</th><th>Created</th><th>Already existed</th><th>Duplicates skipped</th><th>Dates to verify</th></tr></thead><tbody>{results.map(r => <tr key={r.company}><td><span className="company-cell"><i>{initials(r.name)}</i>{r.name}</span>{r.error && <span className="record-meta danger-text">{r.error}</span>}</td><td><Pill value={r.status} /></td><td>{r.created}</td><td>{r.existing}</td><td>{r.duplicates}{r.ruleCovered ? ` (${r.ruleCovered} Rule Library)` : ''}</td><td>{r.needsConfirmation}</td></tr>)}</tbody></table></div>
            <div className="drawer-footer bulk-footer">{failed.length > 0 && <button className="btn primary" onClick={() => createAll(failed.map(r => r.company), run, results)}><RotateCcw size={15} />Retry failed companies</button>}<button className="btn secondary" onClick={() => { setResults(null); setStep(4) }}>Back to preview</button><div /><button className="btn secondary" onClick={() => { setResults(null); setStep(1); setSelected([]); setPlan(null); setRun(''); setDates({}); setConfirmed({}); setExcluded({}); setAssignments({}) }}>Start another setup</button><button className="btn primary" onClick={onDone}><CalendarDays size={15} />Open calendar</button></div>
        </section> })()}
        {step < 5 && <div className="wizard-nav">{step > 1 && <button className="btn secondary" disabled={!!progress} onClick={() => setStep(step - 1)}><ChevronLeft size={15} />Back</button>}<div />{step === 4 && plan && <span className="muted">{s.new ? `${plural(s.new, 'new entry', 'new entries')} for ${plural(plan.companies.filter((c: any) => c.eligible && c.counts.new > 0).length, 'company', 'companies')}` : 'Nothing new to create'}</span>}{step < 4 ? <button className="btn primary" disabled={!stepOk || (step === 3 && (!plan || !!planError))} onClick={() => { setStep(step + 1); if (step === 2) setOpen([]) }}>{step === 3 ? 'Preview entries' : 'Continue'}<ChevronRight size={15} /></button> : <button className="btn primary" disabled={!plan || loading || !!planError || !s.new || !!progress} onClick={() => setConfirming(true)}><Building2 size={15} />Create Calendars for Selected Companies</button>}</div>}
        {confirming && plan && <Dialog overline="CONFIRM BULK CREATION" title="Create calendars for the selected companies?" onClose={() => setConfirming(false)} footer={<><button className="btn secondary" onClick={() => setConfirming(false)}>Back to preview</button><button className="btn primary" onClick={() => { const id = run || crypto.randomUUID(); setRun(id); createAll(eligibleIds(), id) }}>Create {plural(s.new, 'entry', 'entries')}</button></>}>
            <div className="drawer-content"><dl className="record-facts"><div><dt>Template</dt><dd>{s.template} · version {s.templateVersion}</dd></div><div><dt>Financial year</dt><dd>{plan.financialYear}</dd></div><div><dt>Companies</dt><dd>{s.eligibleCompanies}{s.eligibleCompanies !== s.companies ? ` (${s.companies - s.eligibleCompanies} not eligible, skipped)` : ''}</dd></div><div><dt>New entries</dt><dd>{s.new}</dd></div><div><dt>Skipped</dt><dd>{s.existing} existing · {s.duplicates} duplicates</dd></div><div><dt>Dates to verify</dt><dd>{s.needsConfirmation}</dd></div></dl><div className="context-note"><ShieldCheck size={18} /><span>Each company is saved separately and the run is logged in the audit trail. Existing entries, rules and other companies’ calendars are not changed. No reminder or email is sent now: reminders appear in the in-app inbox as each date approaches.</span></div></div>
        </Dialog>}
        {progress && createPortal(<div className="drawer-overlay progress-overlay"><div className="upload-dialog" role="alertdialog" aria-modal="true" aria-labelledby="bulk-progress-title" aria-busy="true"><header><div><span className="overline">BULK CREATION</span><h2 id="bulk-progress-title">Creating calendars…</h2></div></header><div className="drawer-content"><div className="progress-bar" role="progressbar" aria-valuemin={0} aria-valuemax={progress.total} aria-valuenow={progress.done}><i style={{ width: (progress.total ? progress.done / progress.total * 100 : 0) + '%' }} /></div><p className="muted"><Loader2 size={15} className="spin" /> {progress.done} of {progress.total} companies done{progress.current ? ` · now ${progress.current}` : ''}. Keep this page open.</p></div></div></div>, document.body)}
    </>;
}
